describe('conversation list message handling', () => {
  it('lists the authenticated user conversations and serializes their dates', async () => {
    const sent: OutgoingMessage[] = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const listFor = jest.fn(() => summaries);
    const store = {listFor} as unknown as SessionStore;
    const handler = createMessageHandler({} as ChatOrchestrator, store, {history: {enabled: true}});
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};
    const before: ConversationCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    await handler(ws, session, {type: 'list_conversations', limit: 10, before, userId: 'u2'});

    expect({called: listFor.mock.calls, sent}).toEqual({
      called: [['u1', {limit: 10, before}]],
      sent: [
        {
          type: 'conversation_list',
          conversations: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('refuses conversation history when the feature is disabled', async () => {
    const sent: OutgoingMessage[] = [];
    const listFor = jest.fn(() => []);
    const store = {listFor} as unknown as SessionStore;
    const handler = createMessageHandler({} as ChatOrchestrator, store);
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};

    await handler(ws, session, {type: 'list_conversations'});

    expect({sent, calls: listFor.mock.calls}).toEqual({
      sent: [{type: 'error', code: 'UNSUPPORTED', message: 'Conversation history is not available'}],
      calls: [],
    });
  });

  it('answers a failing store without logging its detail', async () => {
    const sent: OutgoingMessage[] = [];
    const secret = 'mongodb://user:password@example.test';
    const listFor = jest.fn(async () => {
      throw new Error(secret);
    });
    const store = {listFor} as unknown as SessionStore;
    const error = jest.fn();
    setLogger({debug: jest.fn(), info: jest.fn(), warn: jest.fn(), error});

    try {
      const handler = createMessageHandler({} as ChatOrchestrator, store, {history: {enabled: true}});
      const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
      const session: ChatSession = {sessionId: 'active', userId: 'u1', entries: []};

      await handler(ws, session, {type: 'list_conversations'});

      expect({sent, errorCalls: error.mock.calls}).toEqual({
        sent: [{type: 'error', code: 'SERVER_ERROR', message: 'Failed to list conversations'}],
        errorCalls: [['ws', 'conversation list failed', {sessionId: 'active', error: 'Error'}]],
      });
    } finally {
      setLogger();
    }
  });
});
import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_conversations and names invalid limit or before fields', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_conversations',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });

    expect(validateMessage({type: 'list_conversations', limit: 0})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_conversations', limit: 201})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_conversations', limit: 1.5})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_conversations', limit: '10'})).toEqual({
      valid: false,
      error: expect.stringContaining('limit'),
    });
    expect(validateMessage({type: 'list_conversations', before: 'not a date'})).toEqual({
      valid: false,
      error: expect.stringContaining('before'),
    });
  });

  it('rejects a cursor session id longer than 128 characters', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      })
    ).toEqual({valid: false, error: expect.stringContaining('sessionId')});
  });
});
import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage | LegacyListSessionsMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

interface LegacyListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: {updatedAt: string; sessionId: string};
}

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_conversations':
      return validateListConversationsMessage(message);
    case 'list_sessions':
      return validateLegacyListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 200)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null) {
      return {valid: false, error: 'list_conversations before must be a cursor object'};
    }

    const before = message.before as Record<string, unknown>;
    if (typeof before.updatedAt !== 'string' || !Number.isFinite(Date.parse(before.updatedAt))) {
      return {valid: false, error: 'list_conversations before.updatedAt must be a valid date string'};
    }
    if (typeof before.sessionId !== 'string' || before.sessionId.length === 0 || before.sessionId.length > 128) {
      return {valid: false, error: 'list_conversations before.sessionId must be 1-128 characters'};
    }

    return {
      valid: true,
      data: {
        type: 'list_conversations',
        limit: typeof limit === 'number' ? limit : undefined,
        before: {updatedAt: before.updatedAt, sessionId: before.sessionId},
      },
    };
  }

  return {
    valid: true,
    data: {type: 'list_conversations', limit: typeof limit === 'number' ? limit : undefined},
  };
}

function validateLegacyListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result = validateListConversationsMessage({...message, type: 'list_conversations'});
  if (!result.valid) return result;
  if (result.data.type !== 'list_conversations') return {valid: false, error: 'Invalid list_sessions frame'};
  return {valid: true, data: {type: 'list_sessions', limit: result.data.limit, before: result.data.before}};
}
import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import type {HalServer, HalServerOptions} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.

const servers: Array<{stop: () => Promise<void>}> = [];
const clients: WebSocket[] = [];

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

export const delegatingTo = (inner: SessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});

export async function stopTrackedEngines(
  clientsToStop: WebSocket[],
  serversToStop: Array<{wss: {clients: {size: number}}; stop: () => Promise<void>}>
): Promise<void> {
  for (const client of clientsToStop.splice(0)) client.terminate();
  for (const hal of serversToStop.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);
  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
  return {client, finished};
